import java.util.*;
import java.io.*;

public class Main {
    static final int MOD = 1000000007;

    static class ModInt {
        int val;

        ModInt(long v) {
            v %= MOD;
            if (v < 0) v += MOD;
            val = (int) v;
        }

        static int modInv(int a, int m) {
            int g = m, r = a, x = 0, y = 1;
            while (r != 0) {
                int q = g / r;
                int tmp = g % r;
                g = r;
                r = tmp;
                int tmpX = x - q * y;
                x = y;
                y = tmpX;
            }
            return x < 0 ? x + m : x;
        }

        ModInt add(ModInt other) {
            int res = val + other.val;
            if (res >= MOD) res -= MOD;
            return new ModInt(res);
        }

        ModInt subtract(ModInt other) {
            int res = val - other.val;
            if (res < 0) res += MOD;
            return new ModInt(res);
        }

        static long fastMod(long x, int m) {
            return x % m;
        }

        ModInt multiply(ModInt other) {
            long res = fastMod((long) val * other.val, MOD);
            return new ModInt(res);
        }

        ModInt divide(ModInt other) {
            return this.multiply(new ModInt(modInv(other.val, MOD)));
        }

        ModInt pow(long p) {
            if (p < 0) throw new IllegalArgumentException("Negative exponent");
            ModInt result = new ModInt(1);
            ModInt base = new ModInt(val);
            while (p > 0) {
                if ((p & 1) == 1) result = result.multiply(base);
                base = base.multiply(base);
                p >>= 1;
            }
            return result;
        }

        ModInt inv() {
            return new ModInt(modInv(val, MOD));
        }

        @Override
        public boolean equals(Object o) {
            if (this == o) return true;
            if (!(o instanceof ModInt)) return false;
            ModInt modInt = (ModInt) o;
            return val == modInt.val;
        }

        @Override
        public int hashCode() {
            return Objects.hash(val);
        }
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        int N = Integer.parseInt(br.readLine().trim());

        ModInt[][] probability = new ModInt[N][N];
        for (int i = 0; i < N; i++) {
            String[] parts = br.readLine().trim().split("\\s+");
            for (int j = 0; j < N; j++) {
                int p = Integer.parseInt(parts[j]);
                probability[i][j] = new ModInt(p).divide(new ModInt(100));
            }
        }

        Map<List<Boolean>, ModInt> possibleMasks = new HashMap<>();
        List<Boolean> starting = new ArrayList<>(Collections.nCopies(1 << N, false));
        starting.set(0, true);
        possibleMasks.put(starting, new ModInt(1));

        for (int left = 0; left < N; left++) {
            Map<List<Boolean>, ModInt> newPossibleMasks = new HashMap<>();
            for (int current = 0; current < (1 << N); current++) {
                ModInt product = new ModInt(1);
                for (int right = 0; right < N; right++) {
                    boolean bitSet = ((current >> right) & 1) != 0;
                    if (bitSet) {
                        product = product.multiply(probability[left][right]);
                    } else {
                        product = product.multiply(new ModInt(1).subtract(probability[left][right]));
                    }
                }
                for (Map.Entry<List<Boolean>, ModInt> entry : possibleMasks.entrySet()) {
                    List<Boolean> possible = entry.getKey();
                    ModInt prob = entry.getValue();
                    List<Boolean> newPossible = new ArrayList<>(Collections.nCopies(1 << N, false));
                    for (int mask = 0; mask < (1 << N); mask++) {
                        if (possible.get(mask)) {
                            for (int i = 0; i < N; i++) {
                                if (((current >> i) & 1) != 0 && ((mask >> i) & 1) == 0) {
                                    newPossible.set(mask | (1 << i), true);
                                }
                            }
                        }
                    }
                    newPossibleMasks.merge(newPossible, prob.multiply(product), (a, b) -> a.add(b));
                }
            }
            possibleMasks = newPossibleMasks;
        }

        ModInt answer = new ModInt(0);
        for (Map.Entry<List<Boolean>, ModInt> entry : possibleMasks.entrySet()) {
            List<Boolean> mask = entry.getKey();
            if (mask.get((1 << N) - 1)) {
                answer = answer.add(entry.getValue());
            }
        }
        System.out.println(answer.val);
    }
}
